mapper.select:
SELECT pos AS name, count(*) AS count FROM bbx_restaurant_card_record WHERE occur_time >= #{minDay} AND occur_time <= #{maxDay} AND pos IS NOT NULL AND deleted = 1
and tenant_id =#{tenantId}
GROUP BY pos

SELECT pos AS name, ROUND(ABS(SUM(trade_amount)), 2) AS amount FROM bbx_restaurant_card_record WHERE occur_time >= #{minDay} AND occur_time <= #{maxDay} AND pos IS NOT NULL AND deleted = 1
and tenant_id =#{tenantId}
GROUP BY pos

SELECT TO_CHAR(occur_time, 'dd') AS time, card_no as cardNo, ROUND(ABS(SUM(trade_amount)), 2) AS amount FROM bbx_restaurant_card_record WHERE occur_time >= #{minDay} AND occur_time <= #{maxDay} AND card_no IS NOT NULL AND deleted = 1
and tenant_id =#{tenantId}
GROUP BY TO_CHAR(occur_time, 'dd'), card_no

SELECT
ROUND(
    COALESCE(
        DATEDIFF(
            DAY,
            MIN(occur_time),
            MAX(occur_time)
        ),
        1
    ),
    2
) AS timeDiffDays
FROM bbx_restaurant_card_record
WHERE deleted = 1

    and tenant_id =#{tenantId}


    and file_id =#{fileId}

SELECT card_no AS cardNo, ROUND(COALESCE(SUM(ABS(trade_amount)), 0), 2) AS totalTradeAmount, COUNT(CASE WHEN card_no IS NOT NULL AND trade_amount IS NOT NULL THEN 1 END) AS totalConsumeCount FROM bbx_restaurant_card_record WHERE deleted = 1
and tenant_id =#{tenantId}
and file_id =#{fileId}
GROUP BY card_no

WITH latest_card_record AS ( SELECT card_no, MAX(occur_time) AS latest_occur_time FROM bbx_restaurant_card_record WHERE card_no IS NOT NULL AND occur_time IS NOT NULL AND deleted = 1
and tenant_id =#{tenantId}
and file_id =#{fileId}
GROUP BY card_no ) SELECT DISTINCT t1.card_no FROM latest_card_record t1 JOIN bbx_restaurant_card_record t2 ON t1.card_no = t2.card_no AND t1.latest_occur_time = t2.occur_time WHERE t2.account_balance < 10 AND t2.account_balance IS NOT NULL AND deleted = 1
and tenant_id =#{tenantId}
and file_id =#{fileId}

WITH latest_card_record AS ( SELECT card_no, MAX(occur_time) AS latest_occur_time FROM bbx_restaurant_card_record WHERE card_no IS NOT NULL AND occur_time IS NOT NULL AND deleted = 1
and tenant_id =#{tenantId}
GROUP BY card_no ) SELECT ROUND(COALESCE(SUM(t2.account_balance), 0), 2) AS totalAccountBalance FROM latest_card_record t1 JOIN bbx_restaurant_card_record t2 ON t1.card_no = t2.card_no AND t1.latest_occur_time = t2.occur_time WHERE t2.account_balance IS NOT NULL AND deleted = 1
and tenant_id =#{tenantId}
